window.HOEREN_TESTS[27] = {"id":"post-und-pakete","name":"Post und Pakete","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Frau Klein, hier ist die Post. Wir haben ein Paket für Sie, das zu groß für Ihren Briefkasten ist. Heute waren Sie nicht zu Hause. Bitte holen Sie es ab in unserer Filiale in der Hauptstraße — bis Freitag. Danach wird es zurückgeschickt. Bitte Ausweis mitbringen.","gender":"f","q":"Was muss Frau Klein tun?","opts":["Auf eine neue Lieferung warten.","Online bestellen.","Das Paket in der Filiale abholen."],"correct":2},{"transcript":"Liebe Kunden, die Postfiliale am Marktplatz hat ab Montag neue Öffnungszeiten. Statt 8 bis 18 Uhr sind wir nun von 9 bis 19 Uhr offen. Samstag bleibt gleich, von 9 bis 12 Uhr. Sonntag sind wir wie immer geschlossen. Wir freuen uns auf Ihren Besuch zur neuen Zeit. Bis bald, tschüss!","gender":"m","q":"Wann öffnet die Post unter der Woche neu?","opts":["Um 9 Uhr.","Um 8 Uhr wie früher.","Um 12 Uhr."],"correct":0},{"transcript":"Hi Tom, hier ist Anna. Hey, das Paket, das ich dir geschickt habe — es ist verloren gegangen. Die Post hat keine Spur mehr. Sie zahlen mir 30 Euro Entschädigung, aber das Buch kann ich nicht ersetzen, das war ein Geschenk. Ich rufe dich später nochmal an.","gender":"f","q":"Was ist passiert?","opts":["Das Paket ist verloren gegangen.","Tom hat es schon bekommen.","Das Paket kam an, aber kaputt."],"correct":0},{"transcript":"Achtung an alle Kunden: Heute ist Großandrang an der Post — vor Weihnachten kommen alle. Bitte planen Sie eine halbe Stunde Wartezeit. Nicht kommen ist schade, und nur am Wochenende kommen hilft heute nicht. Wer nur ein einfaches Paket aufgibt, kann den Paket-Automaten neben der Tür nutzen — viel schneller. Danke für Ihre Geduld.","gender":"f","q":"Was empfiehlt die Post heute?","opts":["Nicht zu kommen.","Nur am Wochenende kommen.","Den Paket-Automaten für einfache Pakete."],"correct":2},{"transcript":"Hallo Lukas, hier ist Mama. Du, das Paket aus Amerika für deinen Geburtstag — es ist endlich da. Aber 25 Euro Zoll musste ich bezahlen. Bitte überweise mir das, wenn du Zeit hast, nicht extra vorbeikommen. Das Paket selbst öffne ich nicht, und du musst es auch nicht selbst abholen, es ist schon bei mir. Das ist deine Überraschung. Schreib mir kurz, wenn das Geld da ist.","gender":"f","q":"Was möchte Mama?","opts":["Lukas soll vorbeikommen.","Lukas soll 25 Euro überweisen.","Lukas soll das Paket selbst abholen."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was bekommt jede Person? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Sonja","gender":"f","text":"Schau mal! Der Briefkasten war heute Morgen ganz voll."},{"speaker":"Uwe","gender":"m","text":"Wir setzen uns an den Tisch und sortieren alles in Ruhe."},{"speaker":"Sonja","gender":"f","text":"Ganz oben liegt etwas Großes aus Berlin."},{"speaker":"Uwe","gender":"m","text":"Das Paket mit einer Tasche ist für dich, Sonja."},{"speaker":"Sonja","gender":"f","text":"Die Farbe gefällt mir sehr. Kommt auch ein Geburtstagsgeschenk für jemanden?"},{"speaker":"Uwe","gender":"m","text":"Nein. Ein Geburtstagsgeschenk ist nicht dabei."},{"speaker":"Sonja","gender":"f","text":"Was liegt direkt darunter?"},{"speaker":"Uwe","gender":"m","text":"Hier liegt eine Steuer-Rechnung für mich. Ich muss zweihundert Euro zahlen."},{"speaker":"Sonja","gender":"f","text":"Das ist ärgerlich, Uwe. Ist auch etwas für Lisa dabei?"},{"speaker":"Uwe","gender":"m","text":"Für Lisa ist eine Postkarte aus dem Ausland dabei. Ihre Freundin schreibt gerade in Spanien."},{"speaker":"Sonja","gender":"f","text":"Sonne und Strand klingen schön. Markus wartet auf Post von der Bank."},{"speaker":"Uwe","gender":"m","text":"Hier ist eine neue Kreditkarte für Markus. Ohne sie kann er nicht zahlen."},{"speaker":"Sonja","gender":"f","text":"Liegt auch eine Mahnung im Stapel?"},{"speaker":"Uwe","gender":"m","text":"Nein. Eine Mahnung haben wir auch keine."},{"speaker":"Sonja","gender":"f","text":"Anna hat gestern etwas zum Lesen bestellt."},{"speaker":"Uwe","gender":"m","text":"Unten liegt ein bestelltes Buch für Anna. Sie liest es heute Abend."},{"speaker":"Sonja","gender":"f","text":"Ich lege die Briefe jetzt in den Schrank."},{"speaker":"Uwe","gender":"m","text":"Die Rechnung bezahle ich morgen früh."}],"options":[{"letter":"a","text":"eine Postkarte aus dem Ausland"},{"letter":"b","text":"einen Werbeprospekt"},{"letter":"c","text":"ein Geburtstagsgeschenk"},{"letter":"d","text":"eine neue Kreditkarte"},{"letter":"e","text":"eine Steuer-Rechnung"},{"letter":"f","text":"ein bestelltes Buch"},{"letter":"g","text":"eine Mahnung"},{"letter":"h","text":"eine Hochzeitseinladung"},{"letter":"i","text":"ein Paket mit einer Tasche"}],"items":[{"person":"Sonja","correct":"i"},{"person":"Uwe","correct":"e"},{"person":"Lisa","correct":"a"},{"person":"Markus","correct":"d"},{"person":"Anna","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mitarbeiter","gender":"m","text":"Guten Tag, wohin schicken Sie das Paket? Inland oder Italien?"},{"speaker":"Kundin","gender":"f","text":"Nach Italien, Mailand. Was kostet das — 15 Euro oder Express 32?"},{"speaker":"Mitarbeiter","gender":"m","text":"Normal-Versand 15 Euro, Express 32 Euro. Express dauert 2 Tage, normal eine Woche. Sie können es auch nicht schicken, aber Sie wollen es ja senden."},{"speaker":"Kundin","gender":"f","text":"Eine Woche ist okay. Express für 32 Euro brauche ich nicht. Normal bitte, 15 Euro."},{"speaker":"Mitarbeiter","gender":"m","text":"Gerne, 15 Euro Normal-Versand nach Mailand. Hier ist der Beleg."}],"q":"Wie viel zahlt die Kundin?","opts":["15 Euro.","32 Euro.","Sie schickt nicht."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, ich brauche Briefmarken für drei Briefe nach Deutschland. Was kostet das ungefähr?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Standard-Briefmarke 0,85 Euro. Macht drei Briefmarken — 2 Euro 55, wenn alle leicht sind. 1 Euro 70 wäre nur ein schwerer Brief."},{"speaker":"Kunde","gender":"m","text":"Sind die Briefe schwer? Vielleicht brauche ich teurere, nicht nur 2 Euro 55?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Lass mich wiegen. Ja, ein Brief ist schwerer — 1 Euro 70. Die zwei leichten 1 Euro 70 zusammen, macht insgesamt 3 Euro 40."},{"speaker":"Kunde","gender":"m","text":"Okay, 3 Euro 40 insgesamt, nicht 2 Euro 55. Hier ist das Geld."}],"q":"Wie viel zahlt der Kunde insgesamt?","opts":["2 Euro 55.","1 Euro 70.","3 Euro 40."],"correct":2},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, mein Paket sollte gestern kommen. Es ist nicht da. Ist es schon bei mir?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Haben Sie die Sendungsnummer? Dann sehe ich, ob es in Hamburg, in München oder schon zugestellt ist."},{"speaker":"Kunde","gender":"m","text":"Hier: 5432. Bei mir zu Hause war nichts."},{"speaker":"Mitarbeiterin","gender":"f","text":"Ihr Paket ist noch in München — kommt morgen oder übermorgen. Nicht in Hamburg und nicht schon bei Ihnen."},{"speaker":"Kunde","gender":"m","text":"Okay, ich warte. München, verstanden. Danke."}],"q":"Wo ist das Paket gerade?","opts":["In München.","In Hamburg.","Schon bei mir."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte eine Postkarte schicken. Ins Ausland, oder geht auch Inland?"},{"speaker":"Mitarbeiter","gender":"m","text":"Wohin genau? Ausland ist teurer, innerhalb Deutschlands günstiger. Selbst bringen können Sie sie natürlich auch."},{"speaker":"Kundin","gender":"f","text":"Inland — nach Hamburg. Ich bringe sie nicht selbst, die Post soll sie schicken. Nicht ins Ausland."},{"speaker":"Mitarbeiter","gender":"m","text":"60 Cent. Hier ist die Marke für innerhalb Deutschlands. Ausland wäre mehr."},{"speaker":"Kundin","gender":"f","text":"Danke, dann nach Hamburg mit der Marke. Super."}],"q":"Wohin geht die Postkarte?","opts":["Ins Ausland.","Innerhalb Deutschlands.","Die Person bringt sie selbst."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, können Sie meine Adresse ändern? Ab heute, oder später?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Ja, alte und neue Adresse bitte. Ab wann gilt sie — heute, nächsten Montag oder nächsten Monat?"},{"speaker":"Mann","gender":"m","text":"Alt: Goethestraße 5. Neu: Schillerstraße 22. Nicht ab heute, ich wohne noch ein paar Tage dort."},{"speaker":"Mitarbeiterin","gender":"f","text":"Ab wann genau? Nächsten Monat ist spät, wenn Sie schon umziehen."},{"speaker":"Mann","gender":"m","text":"Ab Montag nächster Woche, nicht ab heute und nicht erst nächsten Monat."}],"q":"Wann gilt die neue Adresse?","opts":["Ab heute.","Ab nächstem Monat.","Ab nächsten Montag."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Vogel, einer Postbotin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Vogel, Sie sind seit 12 Jahren Postbotin. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Vogel","gender":"f","text":"Ich war früher Verkäuferin in einem Buchladen. Aber ich saß zu viel und brauchte mehr Bewegung. Eine Freundin war bei der Post — sie hat mich angesprochen. Jetzt laufe ich 15 Kilometer pro Tag und bin viel fitter geworden."},{"speaker":"Reporter","gender":"m","text":"Wie ist Ihr typischer Arbeitstag?"},{"speaker":"Vogel","gender":"f","text":"Ich beginne um 6 Uhr morgens — Briefe sortieren, dann ab 8 Uhr raus. Etwa 1500 Briefe und Pakete pro Tag. Im Winter ist es hart — Schnee, Eis, Kälte. Aber Sommer ist schön."},{"speaker":"Reporter","gender":"m","text":"Welcher Stadtteil ist Ihr Bereich?"},{"speaker":"Vogel","gender":"f","text":"Der Stadtteil Nord. Ich kenne meine Kunden gut — viele winken mir, wenn ich vorbeikomme. Manche stellen mir sogar Kaffee raus an heißen Tagen, oder ein warmes Getränk im Winter."},{"speaker":"Reporter","gender":"m","text":"Gibt es Probleme mit Hunden?"},{"speaker":"Vogel","gender":"f","text":"Manchmal. Ich wurde schon zweimal gebissen, beide Male von kleinen Hunden — einem Dackel und einem Pudel. Die großen Hunde sind meistens ruhig. Manche Hunde lieben mich sogar — ich habe immer Leckerli in der Tasche."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie in der Freizeit?"},{"speaker":"Vogel","gender":"f","text":"Lesen! Ironisch, oder? Den ganzen Tag bringe ich Bücher zu anderen, abends sitze ich selbst mit einem Buch. Ich gehe auch nicht mehr spazieren — habe ja schon den ganzen Tag genug Bewegung."}],"items":[{"q":"Sie wurde nur von großen Hunden gebissen.","correct":"nein"},{"q":"Sie läuft 15 Kilometer pro Tag.","correct":"ja"},{"q":"Frau Vogel war früher Buchverkäuferin.","correct":"ja"},{"q":"In ihrer Freizeit liest sie gerne.","correct":"ja"},{"q":"In ihrer Freizeit geht sie viel spazieren.","correct":"nein"}]}]};
